// The bundled brush library (Phase 19, SPEC 1.3.1). No React, no tools.
//
//  - OWN_PRESETS: brushes made by us (defs.ts), tips and grains generated by
//    scripts/brushgen.ts into tips/ and grains/.
//  - OPEN_PRESETS: open-licence brushes (open/**, each with credit + license).
//  - A preset refers to bundled images as "lib:<path>", e.g. "lib:tips/leaf-oak.png"
//    or "lib:open/krita/tips/x.png". The engine resolves those with
//    resolveLibraryAsset (P1 takes it as a resolver function in its options).
//
// Image conventions: tips are grayscale+alpha PNGs (luminance = alpha =
// coverage, white = paint); elongated tips point +x, the direction of travel,
// except grass-blade, flame, streak and flat, which are drawn upright. Grains
// are opaque grayscale 512 px tiles; bright = paint passes.
import type { BrushPreset } from "../schema";
import { OWN_PRESETS, SET_NAMES } from "./defs";

export { OWN_PRESETS, SET_NAMES };
export type { SetName } from "./defs";

const assetUrls = import.meta.glob("./{tips,grains,open}/**/*.png", { eager: true, query: "?url", import: "default" }) as Record<string, string>;
const openJson = import.meta.glob("./open/**/*.json", { eager: true, import: "default" }) as Record<string, BrushPreset>;

/** Open-licence brushes, in file-name order. */
export const OPEN_PRESETS: BrushPreset[] = Object.keys(openJson)
  .sort()
  .map((k) => openJson[k])
  .filter((p): p is BrushPreset => !!p && typeof p.id === "string");

export const LIBRARY_PRESETS: BrushPreset[] = [...OWN_PRESETS, ...OPEN_PRESETS];

/** Bundled set names in display order: ours first, then the open sets. */
export function librarySetNames(): string[] {
  const names: string[] = [...SET_NAMES];
  for (const p of OPEN_PRESETS) if (!names.includes(p.set)) names.push(p.set);
  return names;
}

export function libraryPresetsIn(set: string): BrushPreset[] {
  return LIBRARY_PRESETS.filter((p) => p.set === set);
}

export function libraryPreset(id: string): BrushPreset | undefined {
  return LIBRARY_PRESETS.find((p) => p.id === id);
}

/** True for a "lib:<path>" reference. */
export function isLibraryRef(ref: string): boolean {
  return ref.startsWith("lib:");
}

/**
 * Resolves a "lib:<path>" reference (or the bare path, e.g. "tips/chalk.png")
 * to a URL the browser can load (an image, same origin). Throws for a path
 * that isn't bundled.
 */
export function resolveLibraryAsset(name: string): string {
  const path = name.startsWith("lib:") ? name.slice(4) : name;
  const url = assetUrls[`./${path}`];
  if (url === undefined) throw new Error(`Unknown bundled brush image: ${name}`);
  return url;
}
